Status collect_exact_dynamic_reports(CommonStore& common,SocialState& social,const ExactResultTimeRead& results,const ExactResultReadStamp& stamp,const WorldMoment& now,const CatalogIdentity& catalog){
 if(!social.dynamic||!social.dynamic->time2||!social_time2_version(social.dynamic->version))return common_failure("ExactSocialStateRequired");const auto& identity=results.source_identity();const auto& actual=common.state().identity;if(identity.world_id!=actual.world_id||identity.execution_epoch!=actual.execution_epoch||identity.revision!=actual.revision||identity.tick!=actual.tick)return common_failure("ExactSocialReadIdentityMismatch",{},ErrorKind::internal);auto at=compare_world_moments(now,results.source_moment());if(!at.ok)return {false,{},at.error};if(at.value)return common_failure("ExactSocialReadMomentMismatch",{},ErrorKind::internal);
 auto& state=*social.dynamic;auto& time=*state.time2;auto cursor=time.collection_cursor.last_scanned_fact_id;const auto through=results.last_fact_id();bool complete=false;
 while(!complete){auto page=results.fact_ids_after_source_cursor(cursor,through,64,stamp);if(!page.ok)return {false,{},page.error};for(const auto& id:page.value.ids){auto reportable=results.reportable_fact(id,stamp);if(!reportable.ok)return {false,{},reportable.error};if(!reportable.value)continue;auto actual_fact=results.fact_v2_borrowed(id,stamp);if(!actual_fact.ok)return {false,{},actual_fact.error};if(!actual_fact.value)return common_failure("ExactReportFactMissing",id,ErrorKind::internal);const auto& f=*actual_fact.value;const StableId report_id="report:"+id;if(state.reports.find(report_id))return common_failure("ExactCollectionPrefixConflict",report_id,ErrorKind::internal);Report report;report.id=report_id;report.fact_id=id;report.payload_kind=f.kind;report.observation_tick=f.occurred_at.half_day_tick;report.observation=legacy_report_projection(f);report.visibility_scope=f.publicly_visible?ReportVisibility::local_public:ReportVisibility::participants;report.reliability_kind=f.rule_version=="regional_life_v1"?ReportReliability::witnessed:ReportReliability::official;if(!f.participants.empty())report.origin_subject=f.participants.front().subject;else if(f.supply)report.origin_subject={SubjectKind::organization,f.supply->organization_id};else if(f.obligation)report.origin_subject={SubjectKind::organization,f.obligation->principal_id};else return common_failure("ExactReportOriginRequired",id,ErrorKind::internal);
  SocialTimeSource origin;if(const auto* owner=std::get_if<OwnerFactMoment>(&f.time_basis))origin=SocialExactSource{MomentOwnerSource{owner->source,owner->source_schema}};else origin=SocialLegacyBoundary{std::get<LegacyFactBoundary>(f.time_basis).original_tick,catalog};const auto* header=common.state().facts.find(id);if(!header||header->kind!=f.kind)return common_failure("ExactReportHeaderMismatch",id,ErrorKind::internal);const SourceRef original{header->domain,header->kind,id};const auto time_key=social_time_key(ReportObservationKey{report_id});if(!time.source_time_bindings.insert(time_key,{ReportObservationKey{report_id},std::move(origin),original}))return common_failure("DuplicateReportTimeBinding",report_id);state.reports.insert(report_id,std::move(report));
  auto observers=results.direct_fact_observers_borrowed(id,stamp);if(!observers.ok)return {false,{},observers.error};std::set<StableId> seen;for(const auto& receiver:*observers.value){const auto key=social_subject_key(receiver);if(receiver.id.empty()||!seen.insert(key).second||(receiver.kind==SubjectKind::actor&&!common.actor(receiver.id)))return common_failure("InvalidDirectReportObserver",id,ErrorKind::internal);if(!state.known_reports.find(key))state.known_reports.insert(key,{});state.known_reports.find(key)->insert(report_id,{receiver,report_id,{},now.half_day_tick,receiver});SocialKnowledgeKey knowledge{receiver,report_id};SocialSourceTimeBinding learned{knowledge,SocialExactMoment{now},{"social","report_participant",report_id}};auto cut=capture_social_knowledge_cut(common,state.version,learned);if(!cut.ok)return cut;if(!time.source_time_bindings.insert(social_time_key(knowledge),std::move(learned)))return common_failure("DuplicateDirectReportKnowledge",report_id);}
 }
 cursor=page.value.last_scanned_fact_id;complete=page.value.complete;
 }
 // One candidate commits the whole required collection prefix. Dispatch remains in its own bounded schedule.
 time.collection_cursor={cursor,now};state.last_collected_tick=now.half_day_tick;return common_success();
}
